    m.add_class::<F64Array>()?;
    m.add_class::<Counter>()?;
    m.add_class::<Level>()?;
    m.add_class::<Mode>()?;
    m.add("Error", m.py().get_type::<Error>())?;
    m.add_function(wrap_pyfunction!(counters, m)?)?;
    m.add_function(wrap_pyfunction!(describe, m)?)?;
    m.add_function(wrap_pyfunction!(describe_owned, m)?)?;
